counter/__init__.py:
"""Tiny Counter library — persist."""

from __future__ import annotations

import json
from pathlib import Path


class Counter:
    def __init__(self, value: int = 0) -> None:
        self.value = int(value)

    def inc(self, n: int = 1) -> int:
        self.value += int(n)
        return self.value

    def dec(self, n: int = 1) -> int:
        self.value -= int(n)
        return self.value

    def save(self, path: str | Path) -> None:
        Path(path).write_text(json.dumps({"value": self.value}), encoding="utf-8")

    @classmethod
    def load(cls, path: str | Path) -> Counter:
        data = json.loads(Path(path).read_text(encoding="utf-8"))
        return cls(value=int(data["value"]))

counter_cli.py:
"""CLI over Counter — show / inc / dec with counter.json."""

from __future__ import annotations

import sys
from pathlib import Path

from counter import Counter

STORE = Path("counter.json")


def _load() -> Counter:
    if STORE.is_file():
        return Counter.load(STORE)
    return Counter()


def main(argv=None) -> int:
    args = list(sys.argv[1:] if argv is None else argv)
    if len(args) != 1 or args[0] not in {"inc", "dec", "show"}:
        print("usage: counter_cli.py <inc|dec|show>", file=sys.stderr)
        return 2
    c = _load()
    cmd = args[0]
    if cmd == "inc":
        c.inc()
    elif cmd == "dec":
        c.dec()
    c.save(STORE)
    print(c.value)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
